from __future__ import annotations

from collections import Counter
from html import escape
from pathlib import Path

from .dossier import build_dossier
from .models import MarketEvent
from .worlddeep import WorldLeadAssessment, load_assessments
from .worldscan import GapCandidate, WorldScanStats

CSS = """
:root{color-scheme:dark;--bg:#06111d;--panel:#0a1725;--panel2:#0d1c2c;--line:#1c3852;--text:#f4f8fc;--muted:#8fa5bb;--blue:#63a9ff;--cyan:#61d5ff;--green:#69df9d;--amber:#ffbd67;--purple:#b990ff}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 62% -8%,#12345b 0,transparent 28%),linear-gradient(135deg,#071522,#050d16 72%);color:var(--text);font:14px/1.5 Inter,"PingFang SC","Microsoft YaHei",system-ui,-apple-system,sans-serif}a{color:inherit;text-decoration:none}.shell{display:grid;grid-template-columns:210px minmax(0,1fr);min-height:100vh}.side{position:sticky;top:0;height:100vh;padding:28px 18px;border-right:1px solid #12283b;background:rgba(4,14,24,.78);backdrop-filter:blur(18px)}.brand{font-size:23px;font-weight:850;letter-spacing:-.03em}.brand:before{content:'◉';color:var(--blue);margin-right:9px}.tagline{font-size:10px;color:#a9bed2;margin:2px 0 34px 30px}.nav a{display:block;padding:12px 14px;margin:5px 0;border-radius:12px;color:#c2d2e2}.nav a.active{background:linear-gradient(90deg,#17365d,#10253d);border:1px solid #27517b;color:#fff}.side-foot{position:absolute;bottom:28px;color:#607991;font-size:11px;line-height:1.8}.main{max-width:1500px;width:100%;margin:auto;padding:30px 34px 70px}.status{display:flex;justify-content:flex-end;gap:18px;color:#8199b0;font-size:11px}.live{color:#80e6a9;border:1px solid #173c31;border-radius:999px;padding:4px 10px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:34px;align-items:center;padding:16px 0 34px}.kicker{font-size:11px;color:var(--cyan);font-weight:800;letter-spacing:.15em;text-transform:uppercase}.hero h1{font-size:clamp(42px,5vw,70px);line-height:1.03;letter-spacing:-.055em;margin:10px 0 18px}.hero h1 span{background:linear-gradient(90deg,#7ed7ff,#7b9fff);-webkit-background-clip:text;color:transparent}.hero p{max-width:720px;color:#b3c3d2;font-size:17px}.buttons{display:flex;gap:10px;margin-top:24px}.button{padding:11px 18px;border-radius:999px;border:1px solid #29445e;background:#0d1c2a;font-weight:700}.button.primary{background:#f2f6fa;color:#08111a}.overview{border:1px solid #29455f;border-radius:17px;padding:22px;background:linear-gradient(145deg,rgba(13,31,49,.92),rgba(6,17,28,.88));box-shadow:0 18px 60px #0004}.overview h2{margin:0 0 4px;font-size:19px}.overview p{margin:0;color:var(--muted)}.overview-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;border-top:1px solid #1c3348;margin-top:18px;padding-top:18px}.overview-grid b{display:block;font-size:29px}.overview-grid span{font-size:11px;color:#91a7bb}.section{margin-top:28px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:12px}.section-head h2{margin:0;font-size:23px}.section-head p{margin:0;color:var(--muted)}.sector-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.sector{min-height:105px;border:1px solid #25425c;border-radius:14px;padding:15px;background:linear-gradient(145deg,#0d2032,#091622)}.sector strong{font-size:15px}.sector .num{font-size:24px;font-weight:800;margin:8px 0 2px}.sector small{color:var(--muted)}.heat{display:flex;gap:3px;margin-top:8px}.heat i{display:block;width:5px;height:16px;border-radius:4px;background:#37668e}.heat i.on{background:var(--cyan)}.opportunity-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{border:1px solid #29435c;border-radius:16px;padding:19px;background:linear-gradient(155deg,rgba(14,31,48,.96),rgba(7,17,27,.96));min-height:265px;display:flex;flex-direction:column}.card.review{border-color:#38634f}.badges{display:flex;gap:6px;flex-wrap:wrap}.badge{padding:4px 8px;border:1px solid #35516b;border-radius:999px;font-size:10px;color:#bcd0e1}.badge.review{background:#804b38;border-color:#aa674c;color:#ffd5c3}.badge.watch{background:#153c64;border-color:#2c6aa0;color:#c5e4ff}.badge.dismiss{background:#263543;color:#42566a}.badge.sector{color:#cdb7ff;border-color:#544676}.card h3{font-size:19px;line-height:1.28;margin:14px 0 8px}.card .plain{color:#aebfd0;margin:0 0 14px}.takeaway{margin-top:auto;padding-top:14px;border-top:1px solid #1b3348;color:#d9e5ef}.takeaway b{color:#fff}.source{margin-top:12px;color:#6ebfff;font-size:12px}.change-list{border:1px solid #203a52;border-radius:15px;overflow:hidden}.change{display:grid;grid-template-columns:150px 1fr 90px;gap:16px;align-items:center;padding:13px 17px;border-bottom:1px solid #183148;background:#091724}.change:last-child{border-bottom:0}.change .who{font-weight:750}.change .what{color:#bdcddd}.change .when{text-align:right;color:#718aa1;font-size:11px}.empty{padding:24px;border:1px dashed #31506b;border-radius:14px;color:var(--muted)}details{margin-top:24px}summary{cursor:pointer;color:#7790a8;font-size:12px}.tech{margin-top:10px;padding:15px;border:1px solid #1b3348;border-radius:13px;color:#7f94a8}.footer{margin-top:34px;padding-top:18px;border-top:1px solid #142b3f;color:#536e87;font-size:11px}@media(max-width:1100px){.shell{grid-template-columns:1fr}.side{display:none}.hero{grid-template-columns:1fr}.sector-grid{grid-template-columns:repeat(2,1fr)}.opportunity-grid{grid-template-columns:1fr 1fr}}@media(max-width:720px){.main{padding:22px 16px}.sector-grid,.opportunity-grid{grid-template-columns:1fr}.overview-grid{grid-template-columns:repeat(2,1fr)}.change{grid-template-columns:1fr}.change .when{text-align:left}.status{justify-content:flex-start}.hero h1{font-size:44px}}
"""

SECTOR_CN={"AI & Technology":"科技与 AI","Energy & Climate":"能源与气候","Healthcare & Biotech":"医疗与生物","Finance & Fintech":"金融与支付","Mobility":"出行与交通","Industry & Robotics":"工业与机器人","Consumer & Society":"消费与社会","Frontier":"前沿科技"}

def _sector(s:str)->str:return SECTOR_CN.get(s,s)
def _badge(v:str)->str:return "review" if v=="REVIEW" else "watch" if v=="WATCH" else "dismiss"
def _verdict(v:str)->str:return {"REVIEW":"值得关注","WATCH":"继续观察","DISMISS":"暂不推荐"}.get(v,v)
def _friendly_supply(a:WorldLeadAssessment)->str:
    if a.supply_coverage=="failed": return "目前公开信息不足，还不能判断现有市场是否已经满足这项需求。"
    if a.supply_coverage=="partial": return "已经找到部分市场信息，但覆盖还不完整，因此暂时只建议持续观察。"
    if a.final_recommendation=="DISMISS": return "现有替代方案较多，暂时没有看到明显的市场空位。"
    if a.final_recommendation=="REVIEW": return "现有解决方案仍可能没有完整覆盖这批新需求，值得进一步研究。"
    return "市场已有一些解决方案，但是否存在明显空位还需要更多证据。"

def _assessment_card(c:GapCandidate,a:WorldLeadAssessment)->str:
    return f'''<article class="card {a.final_recommendation.lower()}"><div class="badges"><span class="badge {_badge(a.final_recommendation)}">{_verdict(a.final_recommendation)}</span><span class="badge sector">{escape(_sector(c.sector))}</span></div><h3>{escape(c.headline)}</h3><p class="plain">{escape(c.why_now)}</p><div class="takeaway"><b>我们看到的机会：</b> {escape(c.gap_hypothesis)}<br><br>{escape(_friendly_supply(a))}</div><a class="source" href="{escape(c.url)}" target="_blank">查看原始信息 ↗</a></article>'''

def _change_row(c:GapCandidate)->str:
    return f'''<div class="change"><div class="who">{escape(_sector(c.sector))}</div><div class="what"><b>{escape(c.headline)}</b><br><span>{escape((c.summary or c.why_now)[:190])}</span></div><div class="when">{escape((c.published_at or '刚刚')[:10])}</div></div>'''

def render_dashboard(events:list[MarketEvent],output:Path,world_candidates:list[GapCandidate]|None=None,scan_stats:WorldScanStats|None=None)->None:
    output.parent.mkdir(parents=True,exist_ok=True); world_candidates=world_candidates or []; assessments=load_assessments(Path('data/world-assessments.json')); by_id={a.candidate_id:a for a in assessments}; pairs=[(c,by_id[c.id]) for c in world_candidates if c.id in by_id]; order={'REVIEW':0,'WATCH':1,'DISMISS':2}; pairs.sort(key=lambda x:(order.get(x[1].final_recommendation,9),x[0].published_at or ''),reverse=False)
    review=sum(a.final_recommendation=='REVIEW' for _,a in pairs); watch=sum(a.final_recommendation=='WATCH' for _,a in pairs); deep=len(pairs); stats=scan_stats; raw=stats.raw_entries if stats else len(world_candidates)
    counts=Counter(c.sector for c in world_candidates); revs=Counter(c.sector for c,a in pairs if a.final_recommendation=='REVIEW')
    sectors=''.join(f'''<div class="sector"><strong>{escape(_sector(s))}</strong><div class="num">{n}</div><small>今日关键变化 · {revs[s]} 个值得重点看</small><div class="heat">{''.join('<i class="on"></i>' if i<min(5,n) else '<i></i>' for i in range(5))}</div></div>''' for s,n in counts.most_common(8)) or '<div class="empty">今天暂未发现明显的行业变化。</div>'
    opportunities=''.join(_assessment_card(c,a) for c,a in pairs if a.final_recommendation!='DISMISS') or '<div class="empty">今天暂时没有足够证据支持的重点机会。没有推荐也是雷达的正常结果。</div>'
    changes=''.join(_change_row(c) for c in world_candidates[:16]) or '<div class="empty">暂无新的重要变化。</div>'
    hidden=''.join(f'<div class="tech">{escape(e.headline)} · {escape(build_dossier(e.verify()).verdict)}</div>' for e in events)
    html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GapRadar</title><style>{CSS}</style></head><body><div class="shell"><aside class="side"><div class="brand">GapRadar</div><div class="tagline">See Change. Find Opportunity.</div><nav class="nav"><a class="active" href="#top">⌂　首页</a><a href="#opportunities">◇　今日机会</a><a href="#sectors">▥　行业雷达</a><a href="#changes">◎　全球动态</a></nav><div class="side-foot">A calmer, smarter way<br>to see what's next.<br><br>AMAZING KIMI</div></aside><main class="main" id="top"><div class="status"><span>自动扫描 · 每 6 小时</span><span class="live">● 雷达在线</span></div><section class="hero"><div><div class="kicker">Global Market Intelligence</div><h1>从世界的变化<br>发现<span>下一个机会</span></h1><p>GapRadar 持续观察全球政策、公司动态、技术进展和市场变化，把值得你花时间了解的机会筛出来。</p><div class="buttons"><a class="button primary" href="#opportunities">查看今日机会　→</a><a class="button" href="#sectors">浏览行业雷达</a></div></div><div class="overview"><h2>全球正在发生变化</h2><p>机器负责扫描和筛选，你只需要看最后值得关注的部分。</p><div class="overview-grid"><div><b>{raw}</b><span>今日扫描资讯</span></div><div><b>{len(world_candidates)}</b><span>关键变化</span></div><div><b>{deep}</b><span>深入分析</span></div><div><b>{review}</b><span>重点机会</span></div></div></div></section><section class="section" id="sectors"><div class="section-head"><div><h2>行业雷达</h2><p>哪些领域今天变化最活跃？</p></div><p>{len(counts)} 个行业有新信号</p></div><div class="sector-grid">{sectors}</div></section><section class="section" id="opportunities"><div class="section-head"><div><h2>今日推荐机会</h2><p>基于最新变化，我们认为这些方向最值得你继续看。</p></div><p>{review} 个重点 · {watch} 个观察</p></div><div class="opportunity-grid">{opportunities}</div></section><section class="section" id="changes"><div class="section-head"><div><h2>全球重要变化</h2><p>今天发现的其他值得了解的变化。</p></div><p>共 {len(world_candidates)} 条</p></div><div class="change-list">{changes}</div></section><details><summary>查看研究依据与技术验证</summary>{hidden or '<div class="tech">暂无额外技术验证记录。</div>'}</details><div class="footer">GapRadar by AMAZING KIMI · 系统会持续更新判断；“值得关注”代表有进一步研究价值，不代表投资或商业回报承诺。</div></main></div></body></html>'''
    output.write_text(html,encoding='utf-8')
